package dev.eugheist.ttmodern;
final class BedrockPortalWorldClientAudit {
 static volatile boolean checked;static net.minecraft.world.phys.Vec3 previous;static float yaw,pitch;static net.minecraft.world.item.ItemStack held;static boolean saved;static net.minecraft.world.level.GameType mode;static boolean flying,gravity;static float fallDistance;static final net.minecraft.core.BlockPos ORIGIN=new net.minecraft.core.BlockPos(25,4,25);static final java.util.Map<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState> sourceBlocks=new java.util.HashMap<>(),destinationBlocks=new java.util.HashMap<>();
 static void restore(net.minecraft.client.Minecraft mc){if(!saved)return;var server=mc.getSingleplayerServer();var p=server.getPlayerList().getPlayer(mc.player.getUUID());p.teleportTo(server.overworld(),previous.x,previous.y,previous.z,yaw,pitch);sourceBlocks.forEach((pos,state)->server.overworld().setBlock(pos,state,3));destinationBlocks.forEach((pos,state)->server.getLevel(BedrockPortal.DIMENSION).setBlock(pos,state,3));p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,held);p.setGameMode(mode);p.getAbilities().flying=flying;p.setNoGravity(gravity);p.fallDistance=fallDistance;p.onUpdateAbilities();p.inventoryMenu.broadcastChanges();sourceBlocks.clear();destinationBlocks.clear();saved=false;}
 static void tick(net.minecraft.client.Minecraft mc,int tick){try{step(mc,tick);}catch(RuntimeException e){mc.getSingleplayerServer().submit(()->restore(mc)).join();throw e;}}
 static void step(net.minecraft.client.Minecraft mc,int tick){
  if(tick==1040)mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());previous=p.position();yaw=p.getYRot();pitch=p.getXRot();held=p.getMainHandItem().copy();mode=p.gameMode.getGameModeForPlayer();flying=p.getAbilities().flying;gravity=p.isNoGravity();fallDistance=p.fallDistance;saved=true;p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.getAbilities().flying=false;p.setNoGravity(true);p.fallDistance=0;p.onUpdateAbilities();for(int y=3;y<=7;y++){var pos=new net.minecraft.core.BlockPos(25,y,25);sourceBlocks.put(pos,p.level().getBlockState(pos));p.level().setBlock(pos,(y<=4?net.minecraft.world.level.block.Blocks.BEDROCK:net.minecraft.world.level.block.Blocks.AIR).defaultBlockState(),3);}var bedrock=p.server.getLevel(BedrockPortal.DIMENSION);for(int y=250;y<=255;y++){var pos=new net.minecraft.core.BlockPos(25,y,25);destinationBlocks.put(pos,bedrock.getBlockState(pos));bedrock.setBlock(pos,net.minecraft.world.level.block.Blocks.BEDROCK.defaultBlockState(),3);}p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(AwakenedPick.ITEM.get()));p.inventoryMenu.broadcastChanges();p.connection.teleport(25.5,5,25.5,0,90);});
  if(tick==1050){EnchanterClientAudit.check(mc.gameMode.getPlayerMode()==net.minecraft.world.level.GameType.SURVIVAL&&!mc.player.getAbilities().instabuild,"portal test uses actual survival mode packet");EnchanterClientAudit.check(mc.player.getMainHandItem().is(AwakenedPick.ITEM.get()),"portal pick equip packet");mc.gameMode.startDestroyBlock(ORIGIN,net.minecraft.core.Direction.UP);}
  if(tick==1060){EnchanterClientAudit.check(mc.level.getBlockState(ORIGIN).is(BedrockPortal.BLOCK.get()),"actual survival mining packet opens bedrock portal");mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());EnchanterClientAudit.check(p.level().getBlockState(ORIGIN).is(BedrockPortal.BLOCK.get()),"server portal remains after native mining packet");p.connection.teleport(25.5,4.25,25.5,0,0);});}
  if(tick==1090){BedrockVisualAudit.world(mc);EnchanterClientAudit.check(mc.level.dimension().equals(BedrockPortal.DIMENSION)&&Math.abs(mc.player.getX()-25.5)<.1&&mc.player.getY()>249&&mc.player.getY()<254,"natural portal collision sends native dimension transition to chamber");mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());EnchanterClientAudit.check(BedrockPortal.bedrock(p.level()),"server player entered bedrock dimension");p.connection.teleport(25.5,254.25,25.5,0,0);});}
  if(tick==1120){EnchanterClientAudit.check(mc.level.dimension().equals(net.minecraft.world.level.Level.OVERWORLD),"roof portal natural collision returns through native dimension packets");EnchanterClientAudit.check(mc.player.getX()>=-24.5&&mc.player.getX()<=74.5&&mc.player.getZ()>=-24.5&&mc.player.getZ()<=74.5,"original return random offset range");mc.getSingleplayerServer().execute(()->{try{checked=true;System.out.println("TT BEDROCK PORTAL WORLD CLIENT AUDIT: ALL PASS (actual survival mode/mining packets,portal block synchronization,natural collision,bidirectional dimension transitions,original chamber and return offset,restored fixture)");}finally{restore(mc);}});}
 }
}
